"use client";

import { loadFont as loadSans } from "@remotion/google-fonts/InstrumentSans";
import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import type React from "react";
import { useId } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  interpolateColors,
  spring,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_AXES,
  type RadarCompareElementId,
  RINGS,
  radarCompareTimeline,
  ringsOf,
} from "./timeline";

const { fontFamily: sans } = loadSans("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const { fontFamily: serif } = loadSerif("italic", {
  weights: ["400"],
  subsets: ["latin"],
});
const manrope = loadManrope("normal", {
  weights: ["600"],
  subsets: ["latin"],
});

const REMOCN_R_PATH =
  "M 0.01 0.81 C 0.01 1.73, 0.36 2.79, 1.09 4.13 C 4.91 11.04, 13.45 17.16, 21.7 18.9 C 22.94 19.16, 23.18 19.16, 51.39 19.27 C 76.07 19.36, 80.02 19.4, 81.32 19.57 C 89.89 20.69, 96.2 24.68, 99.38 31.01 C 103.19 38.56, 102.53 50.1, 97.91 57.07 C 94.66 61.96, 89.68 64.99, 83.26 66 C 82.81 66.07, 70.18 66.83, 55.2 67.69 C 24.82 69.43, 27.03 69.23, 24.18 70.4 C 19.9 72.15, 14.84 75.7, 10.65 79.89 C 4.86 85.68, 1.3 91.91, 0.25 98.13 C 0.12 98.85, 0.08 103.13, 0.04 116.66 L 0 134.26 9.5 134.26 L 19 134.26 19.05 119.41 C 19.1 103.27, 19.08 103.82, 19.82 101.04 C 21.79 93.65, 27.86 88.75, 36.45 87.63 C 37.23 87.53, 39.41 87.5, 43.57 87.53 C 50.12 87.59, 50.75 87.65, 53.22 88.45 C 56.61 89.56, 59.67 91.86, 62.02 95.07 C 62.52 95.76, 69.35 103.85, 77.2 113.07 C 85.04 122.28, 91.63 130.04, 91.85 130.32 C 92.07 130.59, 92.5 131.34, 92.82 131.97 C 93.52 133.35, 94.11 133.93, 95.06 134.13 C 95.5 134.23, 98.97 134.26, 106.36 134.23 L 117.01 134.19 100.82 113.07 C 91.91 101.45, 84.52 91.78, 84.39 91.57 C 83.36 89.89, 83.66 87.53, 85.09 86 C 85.79 85.25, 86.36 84.94, 88.07 84.38 C 96.18 81.72, 104.15 76.62, 109.97 70.36 C 120.59 58.93, 124.06 44.32, 119.44 30.43 C 114.59 15.81, 101.93 4.02, 87.64 0.83 C 83.93 0.01, 88.09 0.08, 41.85 0.04 L 0.01 0 0.01 0.81 Z";

/** Full logo as on remocn.dev: R mark (0.76em, on the baseline) + "emocn" in Manrope 600. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

// gradients.sh "mesh" palette, used only inside the brand polygon.
const MESH = ["#ecdcf2", "#8796ee", "#2e45b7", "#0e1645"] as const;
const BLOBS: [number, number][] = [
  [16, 20],
  [84, 26],
  [72, 86],
  [22, 80],
  [52, 48],
  [92, 62],
];

export interface RadarCompareProps {
  axes?: string[];
  competitor?: number[];
  brand?: number[];
  brandLabel?: string;
  competitorLabel?: string;
  caption?: string;
  accent?: string;
  /** Color of the brand name, caption and winning axis labels; overrides the theme. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the labels and copy. Load it yourself; Instrument Sans by default. */
  fontFamily?: string;
  /** Frames between brand vertices growing out. */
  stagger?: number;
  /** Number of grid rings. */
  rings?: number;
  /** Replaces the remocn mark when the brand label is "remocn". */
  logo?: React.ReactNode;
  /** Film grain over the scene. */
  grain?: boolean;
  /** Size of the chart and copy, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the grid, the push, each spoke, ring, label
   * and brand vertex, the competitor's outline, the slide and the copy, by
   * the ids in `./timeline`. Frames on the scene timeline, after `delay` and
   * `speed`.
   */
  timing?: Timing<RadarCompareElementId>;
}

const DEFAULT_COMPETITOR = [0.58, 0.66, 0.82, 0.5, 0.62, 0.46];
const DEFAULT_BRAND = [0.94, 0.88, 0.7, 0.86, 0.9, 0.96];

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const TAU = Math.PI * 2;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    hair: "rgba(255,255,255,0.13)",
    hairStrong: "rgba(255,255,255,0.26)",
    comp: "#8E8D93",
    compOver: "rgba(236,234,242,0.78)",
    compFill: "rgba(200,199,205,0.10)",
    meshBase: MESH[3],
    mesh: [MESH[0], MESH[1], MESH[2], MESH[3]],
    meshAlpha: [0.42, 1, 1, 0.9],
    brandFill: 0.82,
    brandStroke: "#9AA8F5",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    hair: "rgba(18,18,20,0.12)",
    hairStrong: "rgba(18,18,20,0.26)",
    comp: "#85837E",
    compOver: "rgba(18,18,20,0.55)",
    compFill: "rgba(18,18,20,0.07)",
    meshBase: "#E4E6F8",
    mesh: [MESH[0], MESH[1], "#B3BEF6", MESH[0]],
    meshAlpha: [0.95, 0.75, 0.8, 0.7],
    brandFill: 0.9,
    brandStroke: "accent",
    grain: 0.045,
  },
} as const;

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={17}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function clamp01(v: number) {
  return Math.min(1, Math.max(0, v));
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function RadarCompare(props: RadarCompareProps) {
  const {
    axes = DEFAULT_AXES,
    competitor = DEFAULT_COMPETITOR,
    brand = DEFAULT_BRAND,
    brandLabel = "remocn",
    competitorLabel = "Kitebase",
    caption,
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sans,
    rings = RINGS.length,
    logo,
    grain = true,
    scale: size = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const frame = useSceneFrame();
  const tAt = (f: number) => Math.max(0, f - delay) * speed;
  const t = tAt(frame);
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    radarCompareTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const span = (e: { start: number; end: number }) => [e.start, e.end];
  const gid = `rc${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const fill =
    background === "transparent" ? "transparent" : (background ?? p.bg);
  const ringList = ringsOf(rings);
  const list = axes.slice(0, 8);
  const n = Math.max(3, list.length);
  const comp = Array.from({ length: n }, (_, i) => clamp01(competitor[i] ?? 0));
  const mine = Array.from({ length: n }, (_, i) => clamp01(brand[i] ?? 0));
  const wins = mine.filter((v, i) => v > comp[i]).length;
  const stroke = p.brandStroke === "accent" ? accent : p.brandStroke;
  const isRemocn = brandLabel.trim().toLowerCase() === "remocn";

  const R = height * 0.28;
  const cy = height * 0.5;
  const centreAt = (tt: number) =>
    interpolate(
      interpolate(tt, span(tl.get("slide")), [0, 1], {
        ...CLAMP,
        easing: EASE_IO,
      }),
      [0, 1],
      [width * 0.5, width * 0.335],
    );
  const cx = centreAt(t);
  const cxRest = centreAt(Infinity);

  const ang = (i: number) => (i / n) * TAU;
  const pt = (r: number, a: number) => ({
    x: cx + r * Math.sin(a),
    y: cy - r * Math.cos(a),
  });
  const poly = (rs: number[]) =>
    `${rs
      .map((r, i) => {
        const q = pt(r, ang(i));
        return `${i === 0 ? "M" : "L"} ${q.x.toFixed(2)} ${q.y.toFixed(2)}`;
      })
      .join(" ")} Z`;

  const stage = interpolate(t, span(tl.get("enter")), [0, 1], CLAMP);
  const scaleAt = (tt: number) =>
    0.965 +
    0.035 *
      interpolate(tt, span(tl.get("push")), [0, 1], {
        ...CLAMP,
        easing: EASE_IO,
      });
  const scale = scaleAt(t);
  // The push eases in and out slowly; it moves while the furthest text, some
  // 700px from the centre, shifts by more than a thousandth of a pixel.
  const pushing =
    Math.abs(scaleAt(tAt(frame + 1)) - scale) * 700 > 1e-3 ||
    Math.abs(scale - scaleAt(tAt(frame - 1))) * 700 > 1e-3;

  const compPts = comp.map((v) => v * R);
  let perim = 0;
  const cum: number[] = [];
  for (let i = 0; i < n; i++) {
    cum.push(perim);
    const a = pt(compPts[i], ang(i));
    const b = pt(compPts[(i + 1) % n], ang(i + 1));
    perim += Math.hypot(b.x - a.x, b.y - a.y);
  }
  const compEl = tl.get("competitor");
  const compDraw = interpolate(t, span(compEl), [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const compFill = interpolate(
    t,
    [
      compEl.start + compEl.beat("fillAt"),
      compEl.start + compEl.beat("fillEnd"),
    ],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );
  const settle = interpolate(t, span(tl.get("settle")), [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const grow = mine.map((_, i) =>
    spring({
      frame: t - tl.get(`vertex:${i}`).start,
      fps,
      config: { damping: 17, stiffness: 110, mass: 0.9 },
    }),
  );
  const brandOn = interpolate(t, span(tl.get("brand")), [0, 1], CLAMP);
  const brandPts = mine.map((v, i) => v * R * (0.06 + 0.94 * grow[i]));

  const hero = interpolate(t, span(tl.get("name")), [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const line2 = interpolate(t, span(tl.get("caption")), [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const line3 = interpolate(t, span(tl.get("legend")), [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const textLeft = width * 0.6;
  const hw = Math.max(1, u);

  return (
    <AbsoluteFill style={{ background: fill, overflow: "hidden" }}>
      <ScaleLayer scale={size}>
        <AbsoluteFill
          style={{
            // The push runs under every other move, so this one tilt covers
            // the labels and the captions as well.
            transform: `scale(${scale})${glide(pushing)}`,
            transformOrigin: "50% 50%",
          }}
        >
          <svg
            width={width}
            height={height}
            style={{ position: "absolute", inset: 0, opacity: stage }}
            aria-hidden
          >
            {list.map((ax, i) => {
              const k = interpolate(t, span(tl.get(`spoke:${i}`)), [0, 1], {
                ...CLAMP,
                easing: EASE_OUT,
              });
              const q = pt(R * k, ang(i));
              return (
                <line
                  key={`s${ax}`}
                  x1={cx}
                  y1={cy}
                  x2={q.x}
                  y2={q.y}
                  stroke={p.hair}
                  strokeWidth={hw}
                />
              );
            })}
            {ringList.map((r, j) => {
              const k = interpolate(t, span(tl.get(`ring:${j}`)), [0, 1], {
                ...CLAMP,
                easing: EASE_OUT,
              });
              return (
                <path
                  key={`r${r}`}
                  d={poly(
                    Array.from({ length: n }, () => r * R * (0.9 + 0.1 * k)),
                  )}
                  fill="none"
                  stroke={j === ringList.length - 1 ? p.hairStrong : p.hair}
                  strokeWidth={hw}
                  strokeLinejoin="round"
                  opacity={k}
                />
              );
            })}

            <defs>
              <clipPath id={`${gid}c`}>
                <path d={poly(brandPts)} />
              </clipPath>
              {p.mesh.map((col, i) => {
                const [bx, by] = BLOBS[i];
                const dx = Math.sin(t / 45 + i * 1.7) * 4;
                const dy = Math.cos(t / 52 + i * 2.3) * 4;
                return (
                  <radialGradient
                    key={`m${col}${bx}`}
                    id={`${gid}m${i}`}
                    cx={(50 + (bx - 50) * 0.72 + dx) / 100}
                    cy={(50 + (by - 50) * 0.72 + dy) / 100}
                    r={0.58}
                  >
                    <stop
                      offset={0}
                      stopColor={col}
                      stopOpacity={p.meshAlpha[i]}
                    />
                    <stop offset={0.68} stopColor={col} stopOpacity={0} />
                  </radialGradient>
                );
              })}
            </defs>
            {brandOn > 0 ? (
              <g
                clipPath={`url(#${gid}c)`}
                opacity={p.brandFill * brandOn * (0.55 + 0.45 * settle)}
              >
                <rect
                  x={cx - R}
                  y={cy - R}
                  width={2 * R}
                  height={2 * R}
                  fill={p.meshBase}
                />
                {p.mesh.map((col, i) => (
                  <rect
                    key={`mr${col}${BLOBS[i][0]}`}
                    x={cx - R}
                    y={cy - R}
                    width={2 * R}
                    height={2 * R}
                    fill={`url(#${gid}m${i})`}
                  />
                ))}
              </g>
            ) : null}
            <path
              d={poly(compPts)}
              fill={p.compFill}
              fillOpacity={compFill * (1 - 0.4 * settle)}
              stroke={interpolateColors(settle, [0, 1], [p.comp, p.compOver])}
              strokeWidth={1.75 * u}
              strokeLinejoin="round"
              strokeDasharray={`${perim * compDraw} ${perim}`}
              opacity={compDraw > 0 ? 1 - 0.3 * settle : 0}
            />
            {compPts.map((r, i) => {
              const q = pt(r, ang(i));
              const f0 = perim > 0 ? cum[i] / perim : 0;
              const k = interpolate(
                compDraw * 1.04 + (compDraw > 0 ? 0.02 : 0),
                [f0, f0 + 0.05],
                [0, 1],
                CLAMP,
              );
              return (
                <circle
                  key={`cd${list[i] ?? i}`}
                  cx={q.x}
                  cy={q.y}
                  r={3 * u}
                  fill={interpolateColors(settle, [0, 1], [p.comp, p.compOver])}
                  opacity={k * (1 - 0.3 * settle)}
                />
              );
            })}

            {brandOn > 0 ? (
              <path
                d={poly(brandPts)}
                fill="none"
                stroke={stroke}
                strokeWidth={2.5 * u}
                strokeLinejoin="round"
                opacity={brandOn}
              />
            ) : null}
            {brandPts.map((r, i) => {
              const q = pt(r, ang(i));
              return (
                <circle
                  key={`bd${list[i] ?? i}`}
                  cx={q.x}
                  cy={q.y}
                  r={4.5 * u}
                  fill={stroke}
                  stroke={p.bg}
                  strokeWidth={2 * u}
                  opacity={brandOn}
                />
              );
            })}
          </svg>

          {list.map((ax, i) => {
            const a = ang(i);
            const k = interpolate(t, span(tl.get(`label:${i}`)), [0, 1], {
              ...CLAMP,
              easing: EASE_OUT,
            });
            const at = (kk: number, x: number) => {
              const r = R + (22 + 6 * (1 - kk)) * u;
              return { x: x + r * Math.sin(a), y: cy - r * Math.cos(a) };
            };
            // Laid out where the label settles; the drift out and the slide
            // with the chart are a transform, since layout rounds a baseline
            // to whole pixels and the label would click along.
            const q = at(k, cx);
            const rest = at(1, cxRest);
            const sx = Math.sin(a);
            const sy = -Math.cos(a);
            const won = mine[i] > comp[i];
            return (
              <div
                key={`l${ax}`}
                style={{
                  position: "absolute",
                  left: rest.x,
                  top: rest.y,
                  transform: `translate(${q.x - rest.x}px, ${q.y - rest.y}px) translate(${-50 + sx * 50}%, ${-50 + sy * 50}%)`,
                  fontFamily,
                  fontWeight: 500,
                  fontSize: 17 * u,
                  letterSpacing: "-0.005em",
                  color: won
                    ? interpolateColors(settle, [0, 1], [p.muted, fg])
                    : p.muted,
                  whiteSpace: "nowrap",
                  opacity: k * stage,
                }}
              >
                {ax}
              </div>
            );
          })}

          <div
            style={{
              position: "absolute",
              left: textLeft,
              top: cy,
              transform: "translateY(-50%)",
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-start",
            }}
          >
            <div
              style={{
                opacity: hero,
                filter:
                  hero < 0.99 ? `blur(${(1 - hero) * 8 * u}px)` : undefined,
                transform: `translateX(${(1 - hero) * 26 * u}px)`,
              }}
            >
              {isRemocn ? (
                (logo ?? <RemocnLogo fontSize={104 * u} color={fg} />)
              ) : (
                <div
                  style={{
                    fontFamily,
                    fontWeight: 500,
                    fontSize: 108 * u,
                    lineHeight: 0.9,
                    letterSpacing: "-0.04em",
                    color: fg,
                    whiteSpace: "nowrap",
                  }}
                >
                  {brandLabel}
                </div>
              )}
            </div>
            <div
              style={{
                marginTop: 24 * u,
                fontFamily,
                fontWeight: 400,
                fontSize: 28 * u,
                lineHeight: 1.25,
                letterSpacing: "-0.015em",
                color: fg,
                maxWidth: width * 0.34,
                textWrap: "balance",
                opacity: line2,
                transform: `translateY(${(1 - line2) * 10 * u}px)`,
              }}
            >
              {caption ?? (
                <>
                  Ahead of {competitorLabel} on{" "}
                  <span
                    style={{
                      fontFamily: serif,
                      fontStyle: "italic",
                      fontWeight: 400,
                      fontSize: "1.18em",
                      letterSpacing: "-0.01em",
                    }}
                  >
                    {wins} of {n}
                  </span>
                  .
                </>
              )}
            </div>
            <div
              style={{
                marginTop: 26 * u,
                display: "flex",
                alignItems: "center",
                gap: 26 * u,
                fontFamily,
                fontWeight: 400,
                fontSize: 17 * u,
                color: p.muted,
                whiteSpace: "nowrap",
                opacity: line3,
                transform: `translateY(${(1 - line3) * 8 * u}px)`,
              }}
            >
              {[
                { name: brandLabel, color: stroke, w: 2.5 },
                { name: competitorLabel, color: p.comp, w: 1.75 },
              ].map((it) => (
                <div
                  key={it.name}
                  style={{ display: "flex", alignItems: "center", gap: 10 * u }}
                >
                  <span
                    style={{
                      width: 18 * u,
                      height: it.w * u,
                      borderRadius: it.w * u,
                      background: it.color,
                    }}
                  />
                  {it.name}
                </div>
              ))}
            </div>
          </div>
        </AbsoluteFill>
      </ScaleLayer>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${fill} 100%)`,
          opacity: 0.6,
        }}
      />
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The grid fading in with its spokes, rings and axis labels, the slow push,
// the competitor's outline drawing round and filling, the brand's shape
// growing out vertex by vertex, the competitor settling back, the chart
// sliding left and the brand name, caption and legend rising in beside it.
// Frames on the 30 fps scene timeline, after `delay` and `speed`. The ids are
// public: a saved `timing` prop refers to them.

export type RadarCompareElementId =
  | "enter"
  | "push"
  | `spoke:${number}`
  | `ring:${number}`
  | `label:${number}`
  | "competitor"
  | "brand"
  | `vertex:${number}`
  | "settle"
  | "slide"
  | "name"
  | "caption"
  | "legend";

export interface RadarCompareTimingProps {
  axes?: string[];
  stagger?: number;
  rings?: number;
}

export const DEFAULT_AXES = [
  "Speed",
  "Quality",
  "Price",
  "Support",
  "Integrations",
  "Docs",
];
export const RINGS = [0.25, 0.5, 0.75, 1];

/** The ring radii, as fractions of the chart radius. */
export function ringsOf(rings: number) {
  return rings === RINGS.length
    ? RINGS
    : Array.from({ length: Math.max(1, rings) }, (_, j) => (j + 1) / rings);
}

// `enter` fades the grid in and `push` scales the scene up over its length.
// `spoke:<i>`, `ring:<j>` and `label:<i>` draw the spokes, rings and axis
// labels, each list a chain. `competitor` draws its outline over its length
// and fills it from `fillAt` to `fillEnd`. `brand` fades the brand shape in;
// `vertex:<i>` springs vertex `i` out from its start, a chain. `settle` dims
// the competitor, `slide` moves the chart left, and `name`, `caption` and
// `legend` rise in beside it, one after another.
export const radarCompareTimeline = defineTimeline<
  RadarCompareElementId,
  RadarCompareTimingProps
>(({ axes = DEFAULT_AXES, stagger = 1.8, rings = RINGS.length }) => {
  const list = axes.slice(0, 8);
  const n = Math.max(3, list.length);
  const ringList = ringsOf(rings);
  const elements: TimelineElement<RadarCompareElementId>[] = [
    { id: "enter", lane: "Grid", label: "Fade in", start: 0, length: 8 },
    { id: "push", lane: "Camera", label: "Push in", start: 0, length: 150 },
    ...list.map(
      (ax, i): TimelineElement<RadarCompareElementId> => ({
        id: `spoke:${i}`,
        lane: "Spokes",
        label: ax,
        start: 2 + i * 2,
        length: 20,
        follows: i > 0 ? `spoke:${i - 1}` : undefined,
      }),
    ),
    ...ringList.map(
      (_, j): TimelineElement<RadarCompareElementId> => ({
        id: `ring:${j}`,
        lane: "Rings",
        label: `Ring ${j + 1}`,
        start: 6 + j * 3,
        length: 20,
        follows: j > 0 ? `ring:${j - 1}` : undefined,
      }),
    ),
    ...list.map(
      (ax, i): TimelineElement<RadarCompareElementId> => ({
        id: `label:${i}`,
        lane: "Labels",
        label: ax,
        start: 10 + i * 2,
        length: 20,
        follows: i > 0 ? `label:${i - 1}` : undefined,
      }),
    ),
    {
      id: "competitor",
      lane: "Competitor",
      label: "Competitor",
      start: 22,
      length: 30,
      beats: { fillAt: 20, fillEnd: 38 },
    },
    {
      id: "brand",
      lane: "Brand",
      label: "Brand",
      start: 56,
      length: 6,
      follows: "competitor",
    },
    ...Array.from(
      { length: n },
      (_, i): TimelineElement<RadarCompareElementId> => ({
        id: `vertex:${i}`,
        lane: "Vertices",
        label: list[i] ?? `Vertex ${i + 1}`,
        start: 58 + i * stagger,
        length: 30,
        follows: i > 0 ? `vertex:${i - 1}` : "brand",
      }),
    ),
    {
      id: "settle",
      lane: "Competitor",
      label: "Settle",
      start: 80,
      length: 20,
      follows: `vertex:${n - 1}`,
    },
    {
      id: "slide",
      lane: "Camera",
      label: "Slide left",
      start: 86,
      length: 32,
      follows: "settle",
    },
    {
      id: "name",
      lane: "Copy",
      label: "Brand name",
      start: 98,
      length: 22,
      follows: "slide",
    },
    {
      id: "caption",
      lane: "Copy",
      label: "Caption",
      start: 106,
      length: 20,
      follows: "name",
    },
    {
      id: "legend",
      lane: "Copy",
      label: "Legend",
      start: 112,
      length: 20,
      follows: "caption",
    },
  ];
  return elements.sort((a, b) => a.start - b.start);
});
